import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c0_blocks.2.act_k10.npy')); b=-11.4166
D=np.load('v0cache.npy'); c=torch.tensor(D[:,0]); xi=torch.tensor(D[:,1:3]); a0=D[:,3:5]
def off(a,c):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0])); return (ang-(75+90*c)+180)%360-180
def lab(a,c):
    o=off(a,c); return np.round(o/45).astype(int)%8
R=torch.tensor([[0.,-1.],[1.,0.]])
@torch.no_grad()
def sim(alpha,lo,hi,thr,sign=1):
    x=xi.clone(); nf=torch.zeros(len(x))
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,A=net.velocity(x,t,c,("blocks.2.act",),count=False)
        if lo<=k<hi:
            f=(A["blocks.2.act"]@w+b>thr).float()
            nf+=f
            v=v - sign*alpha*f[:,None]*(x@R.T)
        x=x-v/20
    return x.numpy(), nf.numpy()
l0=lab(a0,D[:,0]); print('v0 hist',np.bincount(l0,minlength=8))
for alpha in [3,6,10]:
  for (lo,hi) in [(4,11),(6,12)]:
    for thr in [0,2]:
      for s in [1,-1]:
        a,nf=sim(alpha,lo,hi,thr,s); l=lab(a,D[:,0])
        mv=np.linalg.norm(a-a0,axis=1)>0.3
        r=np.linalg.norm(a,axis=1); o=off(a,D[:,0]); betw=np.abs(o-45*np.round(o/45))>15
        print(alpha,lo,hi,thr,s,'tgt',(l==0).mean().round(3),'hist',np.bincount(l,minlength=8),'moved non-tgt',mv[l0!=0].mean().round(3),'between',betw.mean().round(3),'v0betw',(np.abs(off(a0,D[:,0])-45*np.round(off(a0,D[:,0])/45))>15).mean().round(3))

